const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>new Intl.NumberFormat('vi-VN').format(n||0)+'đ';
let snapshot=window.OFFICE_SNAPSHOT||{date:'2026-10-24',updated:'Chưa có dữ liệu',campaigns:[]};
const defaults={agents:[{id:'may',name:'Mây',role:'Phụ trách quảng cáo Arla',color:'pink',campaign:'120257681708840550'},{id:'bo',name:'Bơ',role:'Theo dõi hiệu quả ngân sách',color:'green',campaign:'120257502179140550'},{id:'mi',name:'Mi',role:'Ý tưởng & nội dung',color:'purple',campaign:''}],tasks:[{id:'initial',title:'Kiểm tra phiên bản sản phẩm và nội dung Arla trước khi chạy',agent:'may',due:'',status:'todo'}],activity:[{text:'Văn phòng đã sẵn sàng. Nhân vật chỉ hoạt động trong giao diện quản lý.',time:'Khởi tạo'}]};
let state;try{state=JSON.parse(localStorage.getItem('ababy-office-v1'))||structuredClone(defaults)}catch{state=structuredClone(defaults)}
const uuid=()=>crypto.randomUUID?.()||String(Date.now()+Math.random());
function save(){try{localStorage.setItem('ababy-office-v1',JSON.stringify(state))}catch{toast('Trình duyệt không lưu được dữ liệu. Hãy kiểm tra dung lượng lưu trữ.')}}
function log(text){state.activity.unshift({text,time:new Date().toLocaleString('vi-VN')});state.activity=state.activity.slice(0,20);save()}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000)}
function chibi(c){return `<div class="chibi ${['pink','purple','green','blue'].includes(c)?c:'pink'}"><div class="hair"></div><div class="face"></div><div class="bang"></div><div class="shirt"></div><div class="bow">✿</div></div>`}
function campaign(id){return snapshot.campaigns.find(c=>c.id===id)}
function options(selected){return '<option value="">Chưa phân công chiến dịch</option>'+snapshot.campaigns.map(c=>`<option value="${esc(c.id)}" ${c.id===selected?'selected':''}>${esc(c.name)}</option>`).join('')}
function render(){const active=snapshot.campaigns.filter(c=>c.status==='ACTIVE');$('#budget').textContent=money(active.reduce((s,c)=>s+c.budget,0));$('#spent').textContent=money(snapshot.campaigns.reduce((s,c)=>s+c.spend,0));$('#messages').textContent=snapshot.campaigns.reduce((s,c)=>s+c.messages,0);$('#agent-total').textContent=state.agents.length;$('#task-count').textContent=state.tasks.filter(t=>t.status!=='done').length;$('#sync-label').textContent=`Ngày dữ liệu: ${snapshot.date} · ${snapshot.updated} · Nhập JSON để cập nhật. Không tự đồng bộ.`;
$('#desks').innerHTML=state.agents.map(a=>{const c=campaign(a.campaign);return `<button class="desk-card" data-agent="${esc(a.id)}" aria-label="Mở bàn làm việc của ${esc(a.name)}"><span class="status-pill">${c?'● Được phân công':'○ Chờ giao việc'}</span><div class="desk"><div class="monitor"></div><div class="keyboard"></div><div class="cup">☕</div></div>${chibi(a.color)}<div class="desk-name">${esc(a.name)}<small>${esc(c?.name||a.role)}</small></div></button>`}).join('');
$('#activity').innerHTML=state.activity.slice(0,4).map(a=>`<div class="activity-item"><i></i><div>${esc(a.text)}<small>${esc(a.time)}</small></div></div>`).join('');renderTasks();renderCampaigns()}
function renderTasks(){const statuses={todo:'Cần làm',doing:'Đang làm',done:'Hoàn thành'};$('#task-board').innerHTML=Object.entries(statuses).map(([k,label])=>`<div class="task-column"><h3>${label} · ${state.tasks.filter(t=>t.status===k).length}</h3>${state.tasks.filter(t=>t.status===k).map(t=>`<article class="task-card">${esc(t.title)}<small>${esc(state.agents.find(a=>a.id===t.agent)?.name||'Chưa phân công')}${t.due?' · Hạn '+esc(t.due):''}</small><select data-task="${esc(t.id)}" aria-label="Trạng thái công việc">${Object.entries(statuses).map(([v,l])=>`<option value="${v}" ${v===k?'selected':''}>${l}</option>`).join('')}</select></article>`).join('')||'<div class="empty">Chưa có công việc trong mục này.</div>'}</div>`).join('')}
function renderCampaigns(){$('#campaign-table').innerHTML=`<table><thead><tr><th>Chiến dịch</th><th>Trạng thái</th><th>Ngân sách/ngày</th><th>Đã chi</th><th>Trò chuyện</th><th>Lượt mua*</th></tr></thead><tbody>${snapshot.campaigns.map(c=>`<tr><td>${esc(c.name)}</td><td><span class="tag">${c.status==='ACTIVE'?'Đang bật':c.status==='PAUSED'?'Tạm dừng':esc(c.status||'Chưa rõ')}</span></td><td>${c.budget?money(c.budget):'Trọn đời / chưa có'}</td><td>${money(c.spend)}</td><td>${c.messages}</td><td>${c.purchases}</td></tr>`).join('')}</tbody></table><p class="drawer-note" style="padding:0 15px">* Lượt mua Meta ghi nhận, không phải số đơn giao thành công. Bản dữ liệu không bao gồm mọi chiến dịch nếu nguồn chưa trả đủ.</p>`}
let selectedAgent='';function openAgent(id){const a=state.agents.find(a=>a.id===id);if(!a)return;selectedAgent=id;const c=campaign(a.campaign);$('#drawer').innerHTML=`<div class="drawer-top"><span class="eyebrow">BÀN LÀM VIỆC</span><button class="close" id="close-drawer" aria-label="Đóng">×</button></div><div class="drawer-person">${chibi(a.color)}<div><h2>${esc(a.name)}</h2><p>${esc(a.role)}</p></div></div><label>Chiến dịch phụ trách<select id="assign-campaign">${options(a.campaign)}</select></label><p class="drawer-note">Phân công này được lưu trên trình duyệt của bạn. Nhân vật chưa tự kiểm tra quảng cáo khi bạn đóng văn phòng.</p>${c?`<div class="drawer-metrics"><div>Ngân sách/ngày<b>${money(c.budget)}</b></div><div>Đã chi ngày ${esc(snapshot.date)}<b>${money(c.spend)}</b></div><div>Cuộc trò chuyện<b>${c.messages}</b></div><div>Chi phí / trò chuyện<b>${c.messages?money(Math.round(c.spend/c.messages)):'Chưa có'}</b></div></div><p class="drawer-note">Trạng thái trong bản dữ liệu: <b>${esc(c.status)}</b>. Ngày dữ liệu: ${esc(snapshot.date)}.</p><a class="text-button" target="_blank" rel="noopener" href="https://adsmanager.facebook.com/adsmanager/manage/campaigns?act=244149749597512&selected_campaign_ids=${encodeURIComponent(c.id)}">Mở chiến dịch trên Meta ↗</a>`:'<p class="empty">Chọn một chiến dịch để xem số liệu tại bàn làm việc này.</p>'}<h3>Công việc được giao</h3>${state.tasks.filter(t=>t.agent===id).map(t=>`<div class="mini-task"><span>${esc(t.title)}</span><small>${{todo:'Cần làm',doing:'Đang làm',done:'Xong'}[t.status]}</small></div>`).join('')||'<p class="empty">Chưa có công việc. Giao việc đầu tiên cho nhân vật nhé.</p>'}<button class="secondary" id="agent-task">＋ Giao công việc</button><button class="danger" id="remove-agent">Xóa nhân vật khỏi văn phòng</button>`;$('#overlay').hidden=false;$('#drawer').hidden=false;$('#close-drawer').onclick=closeDrawer;$('#assign-campaign').onchange=e=>{a.campaign=e.target.value;log(`${a.name} được phân công ${campaign(a.campaign)?.name||'lại: chưa chọn chiến dịch'}.`);render();openAgent(id)};$('#agent-task').onclick=()=>openTask(id);$('#remove-agent').onclick=()=>{if(!confirm(`Xóa nhân vật ${a.name}? Các công việc sẽ được giữ lại và bỏ người phụ trách.`))return;state.agents=state.agents.filter(x=>x.id!==id);state.tasks.forEach(t=>{if(t.agent===id)t.agent=''});log(`Đã xóa nhân vật ${a.name}.`);closeDrawer();render()}}
function closeDrawer(){$('#drawer').hidden=true;$('#overlay').hidden=true}$('#overlay').onclick=closeDrawer;document.addEventListener('keydown',e=>{if(e.key==='Escape')closeDrawer()});
function view(name){['office','tasks','campaigns'].forEach(v=>{$('#'+v+'-view').hidden=v!==name;document.querySelector(`[data-view="${v}"]`).classList.toggle('active',v===name)});$('#crumb').textContent={office:'Văn phòng',tasks:'Công việc',campaigns:'Chiến dịch'}[name]}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>view(b.dataset.view));$('#go-tasks').onclick=()=>view('tasks');$('#desks').onclick=e=>{const b=e.target.closest('[data-agent]');if(b)openAgent(b.dataset.agent)};
$('#add-agent').onclick=()=>{$('#agent-form').reset();$('#agent-campaign').innerHTML=options('');$('#agent-dialog').showModal()};document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>b.closest('dialog').close());
$('#agent-form').onsubmit=e=>{e.preventDefault();const d=new FormData(e.target);const name=d.get('name').trim(),role=d.get('role').trim();if(!name||!role)return;state.agents.push({id:uuid(),name,role,color:d.get('color'),campaign:d.get('campaign')});log(`${name} vừa gia nhập văn phòng.`);$('#agent-dialog').close();render();toast('Đã thêm nhân vật vào văn phòng')};
function openTask(agent=''){$('#task-form').reset();$('#task-agent').innerHTML='<option value="">Chưa phân công</option>'+state.agents.map(a=>`<option value="${esc(a.id)}" ${agent===a.id?'selected':''}>${esc(a.name)}</option>`).join('');$('#task-dialog').showModal()}$('#new-task').onclick=()=>openTask();$('#task-form').onsubmit=e=>{e.preventDefault();const d=new FormData(e.target),title=d.get('title').trim();if(!title)return;state.tasks.push({id:uuid(),title,agent:d.get('agent'),due:d.get('due'),status:'todo'});log(`Đã giao việc: ${title}`);$('#task-dialog').close();render();if(!$('#drawer').hidden)openAgent(selectedAgent);toast('Đã lưu công việc')};
$('#task-board').onchange=e=>{if(!e.target.dataset.task)return;const t=state.tasks.find(t=>t.id===e.target.dataset.task);if(!t)return;t.status=e.target.value;log(`Cập nhật tiến độ: ${t.title}`);render()};
$('#import-btn').onclick=()=>$('#import-file').click();$('#import-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>2000000)throw Error('Tệp quá lớn');const d=JSON.parse(await file.text());if(!Array.isArray(d.campaigns)||typeof d.date!=='string')throw Error('Cần date và danh sách campaigns');for(const c of d.campaigns){if(typeof c.id!=='string'||typeof c.name!=='string'||!['budget','spend','messages','purchases'].every(k=>Number.isFinite(c[k])&&c[k]>=0))throw Error('Thông tin chiến dịch không hợp lệ')}snapshot=d;localStorage.setItem('ababy-office-data-v1',JSON.stringify(d));log('Đã nhập bản dữ liệu quảng cáo mới.');render();toast('Đã cập nhật dữ liệu')}catch(err){toast('Không nhập được: '+err.message)}e.target.value=''};
async function init(){try{if(location.protocol==='file:'){const stored=JSON.parse(localStorage.getItem('ababy-office-data-v1')||'null');if(stored&&stored.date>=snapshot.date)snapshot=stored;render();return;}const r=await fetch('snapshot.json');if(!r.ok)throw Error('Không tải được');snapshot=await r.json();const stored=JSON.parse(localStorage.getItem('ababy-office-data-v1')||'null');if(stored&&stored.date>=snapshot.date)snapshot=stored}catch{toast('Chưa tải được dữ liệu quảng cáo. Bạn vẫn có thể giao việc.')}render()}init();

